package com.academy.lms.enrollment;
import com.academy.lms.course.Course;import com.academy.lms.user.User;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="enrollments",uniqueConstraints=@UniqueConstraint(columnNames={"student_id","course_id"})) public class Enrollment{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="student_id")private User student;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="course_id")private Course course;@Column(nullable=false)private short progress;@Column(name="enrolled_at",nullable=false)private Instant enrolledAt;@Column(name="completed_at")private Instant completedAt;protected Enrollment(){}public Enrollment(User s,Course c){id=UUID.randomUUID();student=s;course=c;enrolledAt=Instant.now();}public UUID getId(){return id;}public User getStudent(){return student;}public Course getCourse(){return course;}public short getProgress(){return progress;}public Instant getEnrolledAt(){return enrolledAt;}public Instant getCompletedAt(){return completedAt;}}

